import{_ as e,c as o,o as i,a2 as s}from"./chunks/framework.gSKzFT2J.js";const m=JSON.parse('{"title":"Git Ignore et .gitignore","description":"","frontmatter":{},"headers":[],"relativePath":"fr/advanced/gitignore.md","filePath":"fr/advanced/gitignore.md"}'),d={name:"fr/advanced/gitignore.md"},t=s(`<h1 id="git-ignore-et-gitignore" tabindex="-1">Git Ignore et .gitignore <a class="header-anchor" href="#git-ignore-et-gitignore" aria-label="Permalink to &quot;Git Ignore et .gitignore&quot;">​</a></h1><h2 id="git-ignore" tabindex="-1">Git Ignore <a class="header-anchor" href="#git-ignore" aria-label="Permalink to &quot;Git Ignore&quot;">​</a></h2><p>Lorsque vous partagez votre code avec d&#39;autres, il y a souvent des fichiers ou des parties de votre projet que vous ne souhaitez pas partager.</p><h3 id="exemples" tabindex="-1">Exemples : <a class="header-anchor" href="#exemples" aria-label="Permalink to &quot;Exemples :&quot;">​</a></h3><ul><li>Fichiers de log</li><li>Fichiers temporaires</li><li>Fichiers cachés</li><li>Fichiers personnels</li><li>Etc.</li></ul><p>Git vous permet de spécifier quels fichiers ou parties de votre projet doivent être ignorés à l&#39;aide d&#39;un fichier <code>.gitignore</code>.</p><p>Les fichiers et dossiers spécifiés dans le fichier <code>.gitignore</code> ne seront pas suivis par Git. Cependant, le fichier <code>.gitignore</code> lui-même <strong>est suivi par Git</strong>.</p><h2 id="creer-un-fichier-gitignore" tabindex="-1">Créer un fichier .gitignore <a class="header-anchor" href="#creer-un-fichier-gitignore" aria-label="Permalink to &quot;Créer un fichier .gitignore&quot;">​</a></h2><p>Pour créer un fichier <code>.gitignore</code>, allez dans le répertoire racine de votre projet local Git, puis créez le fichier :</p><h3 id="exemple" tabindex="-1">Exemple : <a class="header-anchor" href="#exemple" aria-label="Permalink to &quot;Exemple :&quot;">​</a></h3><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">touch</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> .gitignore</span></span></code></pre></div><p>Ouvrez ensuite le fichier avec un éditeur de texte.</p><p>Ajoutons simplement deux règles :</p><ol><li>Ignorer tous les fichiers avec l&#39;extension <code>.log</code>.</li><li>Ignorer tous les fichiers dans n&#39;importe quel dossier nommé <code>temp</code>.</li></ol><h3 id="exemple-de-contenu-pour-gitignore" tabindex="-1">Exemple de contenu pour <code>.gitignore</code> : <a class="header-anchor" href="#exemple-de-contenu-pour-gitignore" aria-label="Permalink to &quot;Exemple de contenu pour \`.gitignore\` :&quot;">​</a></h3><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># ignorer tous les fichiers .log</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">*</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">.log</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># ignorer tous les fichiers dans un dossier nommé temp</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">temp/</span></span></code></pre></div><p>Ainsi, tous les fichiers <code>.log</code> et tout le contenu des dossiers <code>temp</code> seront ignorés par Git.</p><p><strong>Note :</strong> Dans ce cas, nous utilisons un seul fichier <code>.gitignore</code> qui s&#39;applique à l&#39;ensemble du dépôt.</p><p>Il est également possible d&#39;avoir des fichiers <code>.gitignore</code> supplémentaires dans des sous-répertoires. Ceux-ci ne s&#39;appliquent qu&#39;aux fichiers ou dossiers de ce répertoire particulier.</p><h2 id="regles-pour-le-fichier-gitignore" tabindex="-1">Règles pour le fichier .gitignore <a class="header-anchor" href="#regles-pour-le-fichier-gitignore" aria-label="Permalink to &quot;Règles pour le fichier .gitignore&quot;">​</a></h2><p>Voici les règles générales pour les modèles dans les fichiers <code>.gitignore</code> :</p><table tabindex="0"><thead><tr><th>Modèle</th><th>Explication/Correspondance</th><th>Exemples</th></tr></thead><tbody><tr><td><code></code></td><td>Les lignes vides sont ignorées</td><td></td></tr><tr><td><code># commentaire texte</code></td><td>Les lignes commençant par <code>#</code> sont ignorées</td><td><code># Fichiers temporaires</code></td></tr><tr><td><code>nom</code></td><td>Correspond à tous les fichiers, dossiers ou fichiers/dossiers dans un dossier nommé <code>nom</code></td><td><code>/nom.log</code>, <code>/nom/fichier.txt</code>, <code>/lib/nom.log</code></td></tr><tr><td><code>nom/</code></td><td>Se termine par <code>/</code>, spécifie que le modèle correspond à un dossier. Cela correspond à tous les fichiers et dossiers dans n&#39;importe quel dossier nommé <code>nom</code>.</td><td><code>/nom/fichier.txt</code>, <code>/nom/log/nom.log</code></td></tr><tr><td><code>nom.fichier</code></td><td>Correspond à tous les fichiers avec le nom <code>nom.fichier</code></td><td><code>/nom.fichier</code>, <code>/lib/nom.fichier</code></td></tr><tr><td><code>/nom.fichier</code></td><td>Commencer par <code>/</code> spécifie que le modèle ne correspond qu&#39;aux fichiers dans le dossier racine</td><td><code>/nom.fichier</code>, mais pas <code>/lib/nom.fichier</code></td></tr><tr><td><code>lib/nom.fichier</code></td><td>Les modèles spécifiant des fichiers dans des dossiers spécifiques sont toujours relatifs à la racine</td><td><code>/lib/nom.fichier</code> mais pas <code>nom.fichier</code>, ni <code>/test/lib/nom.fichier</code></td></tr><tr><td><code>**/lib/nom.fichier</code></td><td>Commencer par <code>**</code> avant <code>/</code> spécifie que le modèle correspond à n&#39;importe quel dossier du dépôt, pas seulement à la racine</td><td><code>/lib/nom.fichier</code>, <code>/test/lib/nom.fichier</code></td></tr><tr><td><code>name[a-z].file</code></td><td><code>[range]</code> correspond à un seul caractère dans la plage spécifiée (dans ce cas, un caractère entre a et z, ou un chiffre)</td><td><code>/namea.file</code>, <code>/nameb.file</code></td></tr><tr><td><code>name[abc].file</code></td><td><code>[set]</code> correspond à un seul caractère dans un ensemble spécifié (dans ce cas, a, b ou c)</td><td><code>/namea.file</code>, <code>/nameb.file</code></td></tr><tr><td><code>name[!abc].file</code></td><td><code>[!set]</code> correspond à un caractère unique, sauf ceux spécifiés dans l&#39;ensemble (dans ce cas, a, b ou c)</td><td><code>/namex.file</code>, mais pas <code>/names.file</code>, <code>/namea.file</code>, <code>/nameb.file</code></td></tr><tr><td><code>*.file</code></td><td>Correspond à tous les fichiers avec l&#39;extension <code>.file</code></td><td><code>/nom.file</code>, <code>/lib/nom.file</code></td></tr><tr><td><code>name/</code></td><td>Correspond à tous les dossiers se terminant par <code>name</code></td><td><code>/lastname/log.file</code>, <code>/firstname/log.file</code></td></tr><tr><td><code>!name/secret.log</code></td><td><code>!</code> spécifie une négation ou une exception. Cela correspond à tous les fichiers et dossiers dans n&#39;importe quel dossier <code>name</code>, sauf <code>name/secret.log</code></td><td><code>/nom/file.txt</code>, <code>/nom/log/nom.log</code>, mais pas <code>/nom/secret.log</code></td></tr><tr><td><code>junk.*</code></td><td>Ajouter de nouveaux modèles après une négation ré-ignorera un fichier précédemment exclu. Cela correspond à tous les fichiers avec l&#39;extension <code>.file</code>, sauf ceux dans le dossier <code>name</code>, sauf si le fichier s&#39;appelle <code>junk</code></td><td><code>/log.file</code>, <code>/name/log.file</code>, mais pas <code>/name/junk.file</code></td></tr></tbody></table><h2 id="ignorer-des-fichiers-locaux-et-personnels" tabindex="-1">Ignorer des fichiers locaux et personnels <a class="header-anchor" href="#ignorer-des-fichiers-locaux-et-personnels" aria-label="Permalink to &quot;Ignorer des fichiers locaux et personnels&quot;">​</a></h2><p>Il est également possible d&#39;ignorer des fichiers ou des dossiers sans qu&#39;ils soient visibles dans le fichier <code>.gitignore</code> distribué.</p><p>Ces types d&#39;ignorances sont spécifiés dans le fichier <code>.git/info/exclude</code>. Il fonctionne de la même manière que <code>.gitignore</code>, mais ces exclusions ne sont visibles par personne d&#39;autre.</p>`,25),r=[t];function c(n,a,l,p,u,h){return i(),o("div",null,r)}const f=e(d,[["render",c]]);export{m as __pageData,f as default};
